{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure EBS volumes are encrypted",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify encryption for the root EBS volume. Unencrypted EBS volumes can expose sensitive data if compromised."
    },
    {
      "check_id": "CKV_AWS_389",
      "title": "Ensure no public IP is assigned",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not explicitly disable public IP assignment. Instances with public IPs can be directly exposed to the internet, increasing the attack surface."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "Require IMDSv2 for instance metadata",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "HIGH",
      "explanation": "The launch configuration does not enforce the use of IMDSv2. Without this, the instance metadata service can be accessed without requiring a token, increasing the risk of metadata exposure."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n\n  root_block_device {\n    encrypted = true\n  }\n\n  associate_public_ip_address = false\n\n  metadata_options {\n    http_tokens = \"required\"\n  }\n}",
  "fix_summary": "Added encryption for the root EBS volume, disabled public IP assignment, and enforced IMDSv2 token requirement to address security risks."
}
